class Solution {
public:
    int shortestSubarray(vector<int>& nums, int k) {
        int n = nums.size();
        vector<long long> prefix(n + 1, 0);
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }
        deque<int> dq;
        int res = INT_MAX;
        for (int j = 0; j <= n; j++) {
            while (!dq.empty() && prefix[j] - prefix[dq.front()] >= k) {
                res = min(res, j - dq.front());
                dq.pop_front();
            }
            while (!dq.empty() && prefix[j] <= prefix[dq.back()]) {
                dq.pop_back();
            }
            dq.push_back(j);
        }
        return res == INT_MAX ? -1 : res;
    }
};

class Solution {
    public int shortestSubarray(int[] nums, int k) {
        int n = nums.length;
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }
        Deque<Integer> dq = new ArrayDeque<>();
        int res = Integer.MAX_VALUE;
        for (int j = 0; j <= n; j++) {
            while (!dq.isEmpty() && prefix[j] - prefix[dq.peekFirst()] >= k) {
                res = Math.min(res, j - dq.pollFirst());
            }
            while (!dq.isEmpty() && prefix[j] <= prefix[dq.peekLast()]) {
                dq.pollLast();
            }
            dq.addLast(j);
        }
        return res == Integer.MAX_VALUE ? -1 : res;
    }
}

var shortestSubarray = function(nums, k) {
    const n = nums.length;
    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] + nums[i];
    }
    const dq = [];
    let head = 0;
    let res = Infinity;
    for (let j = 0; j <= n; j++) {
        while (head < dq.length && prefix[j] - prefix[dq[head]] >= k) {
            res = Math.min(res, j - dq[head]);
            head++;
        }
        while (head < dq.length && prefix[j] <= prefix[dq[dq.length - 1]]) {
            dq.pop();
        }
        dq.push(j);
    }
    return res === Infinity ? -1 : res;
};
